package com.prem.anagram; import java.util.Arrays; public class SortingAnagramChecker { public static boolean isAnagram(String a,String b){if(a==null||b==null)return false; char[] x=a.replaceAll("\\s+","").toLowerCase().toCharArray(),y=b.replaceAll("\\s+","").toLowerCase().toCharArray(); if(x.length!=y.length)return false; Arrays.sort(x);Arrays.sort(y);return Arrays.equals(x,y);} }
